	sections = {
		{
			title = "Resumo",
			text = [=[Ginro Hearthkindle é um soldado do {link:feathermoon-stronghold}Domínio de Plumaluna{/link} que não quis desistir de um amigo. Quando o mensageiro {link:raschal-the-courier}Raschal{/link} desapareceu na estrada para {link:thalanaar}Thalanaar{/link}, Ginro saía todos os dias pela mata para encontrá-lo, e voltava todas as noites com nada além de dentes de {link:gnolls}gnoll{/link}. Mesmo depois que o domínio declarou Raschal perdido, ele continuou procurando.]=],
