		{ text = "Libertado da Colmeia" },
		{ text = "As Boas-vindas de um Herói" },
	},
	bonds = {
		{ id = "raschal-the-courier", name = "Raschal, o Mensageiro", note = "o amigo que ele procurou" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "leu a faca, e lhe deve nas cartas" },
