			title = "Resumo",
			text = [=[Angelas Moonbreeze partilha o amor do marido, {link:troyas-moonbreeze}Troyas{/link}, pelas velhas ruínas, e boa parte de seu saber. Não partilha seu descuido. Quando ele começou a vagar sozinho pela {link:high-wilderness}Selva Alta{/link}, onde mandam os ogros Gordunni, ela pediu discretamente a outros que abrissem o caminho à frente dele, e que nada lhe dissessem.]=],
		},
		{
			title = "Importância",
			text = [=[Os estudos de Angelas vão muito além de {link:feralas}Feralas{/link}. Ela sabe de um templo sob a terra, banido para lá por poderes maiores que qualquer um que ela já viu, e de um estudioso goblin que andou por ele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Pediu que os ogros da {link:high-wilderness}Selva Alta{/link} fossem rechaçados pelo bem do marido.
• Envia quem busca o {link:temple-of-atal-hakkar}Templo Submerso{/link} ao goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link}, em {link:tanaris}Tanaris{/link}.]=],
		},
	},
	mentions = {
		{ text = "A {link:high-wilderness}Selva Alta{/link}" },
		{ text = "O {link:temple-of-atal-hakkar}Templo Submerso{/link}" },
