			title = "Resumo",
			text = [=[Rockbiter é um gigante das colinas do norte de {link:feralas}Feralas{/link}, e um gigante gentil. Ele devia cuidar de {link:shay-leafrunner}Shay Leafrunner{/link}, uma jovem elfa noturna que vive a vagar. Num momento ela estava ao lado dele nas ruínas ao norte de seu acampamento. No seguinte, tinha sumido, e ele não conseguia pensar no que fazer.]=],
		},
		{
			title = "Importância",
			text = [=[Numa floresta onde a maioria dos gigantes é perigosa, Rockbiter lembra que nem todos são. Sua amizade com uma pequena menina elfa é um dos contos mais gentis de {link:feralas}Feralas{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Pediu a um viajante que encontrasse Shay, já que pernas pequenas são mais rápidas que as dele.
• Guarda agora o sino dela, para poder chamá-la de volta.]=],
		},
	},
	mentions = {
		{ text = "O Gigante Guardião" },
		{ text = "Shay, a {link:longwalkers}Andarilha{/link}" },
	},
	bonds = {
		{ id = "shay-leafrunner", name = "Shay Leafrunner", note = "a menina de quem ele cuida" },
	},
})

