})

Translate("ptBR", "hadoken-swiftstrider", {
	title = "Hadoken Swiftstrider",
	subtitle = "Guerreiro da Aldeia Mojache",
	found = "Aldeia Mojache",
	hint = [=[Fale com o líder de guerra que defende a Aldeia Mojache contra os gnolls.]=],
	allegiance = "Horda · Aldeia Mojache",
	aliases = { "Hadoken" },
	sections = {
		{
			title = "Resumo",
			text = [=[Hadoken Swiftstrider comanda a defesa da {link:camp-mojache}Aldeia Mojache{/link}. Não tem paciência para a questão de os gnolls Patábua pertencerem ou não a {link:feralas}Feralas{/link}. Eles atacam sua aldeia e, se a {link:horde}Horda{/link} não se mantiver firme, será expulsa da região. É um veterano que já leu muitos planos de batalha, e reconhece um inimigo desesperado quando vê um.]=],
		},
		{
			title = "Importância",
			text = [=[Hadoken foi o primeiro da {link:horde}Horda{/link} a ver que os gnolls não eram a verdadeira ameaça. Ele seguiu o medo deles para o sul e encontrou os Zukk'ash, e seu relatório sobre eles chegou a {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ordenou que os alfas Patábua fossem abatidos em rápida sucessão para lançar os gnolls no caos.
• Enviou buscadores atrás dos planos de batalha dos gnolls.
• Ordenou que os Zukk'ash da {link:the-writhing-deep}Profundeza Atormentada{/link} fossem reduzidos, e que sua maior fera, {link:stinglasher}Stinglasher{/link}, fosse aberta para estudo.
• Enviou o relatório da aldeia sobre os insetos a Zilzibin Drumlore, em {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Guerra contra os Patábua",
			hint = "Rechace os gnolls que atacam a Aldeia Mojache.",
			text = [=[Os Patábua sempre haviam atacado a aldeia, e a {link:horde}Horda{/link} sempre os havia contido. Ultimamente, os ataques tinham se tornado selvagens e constantes, como se os gnolls não tivessem mais para onde ir. Hadoken pretendia quebrá-los com um único golpe certeiro. Funcionou, por um tempo. Também o fez perguntar-se o que os havia levado a tal frenesi.]=],
		},
		{
			title = "Os Planos de Batalha",
			hint = [=[Encontre os planos de batalha dos gnolls em seus acampamentos do sul.]=],
			text = [=[O mapa dos gnolls contava a história. A maioria de suas setas apontava para o sul, para longe da {link:camp-mojache}Aldeia Mojache{/link}, e ao lado do desenho de um grande inseto havia fileiras de marcas de contagem: seus mortos. Os Patábua travavam uma guerra em duas frentes, e a que estavam perdendo não era contra a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Os Zukk'ash",
			hint = "Leve a Orgrimmar o relatório da aldeia sobre os insetos.",
			text = [=[Hadoken não se importava se os insetos sabiam pensar. Eles estavam empurrando os gnolls para dentro de sua aldeia, e por isso eram seus inimigos. Quando suas descobertas chegaram a Zilzibin Drumlore, em {link:orgrimmar}Orgrimmar{/link}, o goblin deu aos insetos seu verdadeiro nome, silitídeos, e avisou que a {link:horde}Horda{/link} os havia ignorado por tempo demais.]=],
		},
	},
	mentions = {
		{ text = "Guerra contra os Patábua" },
		{ text = "Ataque aos Alfas" },
		{ text = "Investigação Patábua" },
		{ text = "Os Planos de Batalha" },
		{ text = "Infestação Zukk'ash" },
		{ text = "{link:stinglasher}Stinglasher{/link}" },
		{ text = "Relatório Zukk'ash" },
	},
	bonds = {
		{ id = "stinglasher", name = "Stinglasher", note = "a fera que ele queria estudada" },
		{ id = "rok-orhan", name = "Rok Orhan", note = "luta contra os ogros a seu lado" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "ocupa o domínio da Aliança no oeste" },
	},
})

