Translate("ptBR", "witch-doctor-uzer-i", {
	title = "Mandingueiro Uzer'i",
	subtitle = "Mandingueiro da Aldeia Mojache",
	found = "Aldeia Mojache",
	hint = [=[Fale com o mandingueiro troll da Aldeia Mojache que busca um recipiente especial.]=],
	allegiance = "Horda · Aldeia Mojache",
	aliases = { "Uzer'i" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Mandingueiro Uzer'i é um troll da {link:camp-mojache}Aldeia Mojache{/link} e mestre de uma arte antiga e inquietante. Ele conhece o muisek, o espírito que uma criatura deixa para trás quando morre com violência. Tal espírito, ele ensina, pode escapar, buscar vingança e até voltar na forma de uma fera maior. Uzer'i encontrou um modo de impedir isso. Uma criatura encolhida e capturada no momento de sua morte não consegue soltar seu muisek, e um muisek capturado pode ser usado.]=],
		},
		{
			title = "Importância",
			text = [=[O trabalho de Uzer'i é uma arma apontada contra os elfos noturnos. Ele escolhe suas criaturas pelo laço que têm com os {link:night-elves}kaldorei{/link}: os luniscos, outrora os bichos de estimação de Eluna; os hipogrifos, suas montarias leais; os dragões feéricos, seus aliados; os silvanos, seus protetores; e os gigantes da montanha, que desceram de seus picos para ajudá-los contra a {link:burning-legion}Legião Ardente{/link}. A força deles, diz ele, também deveria servir à {link:horde}Horda{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Trocou a cabeça encolhida de um {link:dwarves}anão{/link} com {link:neeru-fireblade}Neeru Fireblade{/link}, de {link:orgrimmar}Orgrimmar{/link}, pelas ervas de que seu recipiente precisava.
• Enviou caçadores até as {link:the-hinterlands}Terras Agrestes{/link} para capturar o muisek dos luniscos.
• Selou os espíritos capturados em armas.]=],
		},
	},
	chapters = {
		{
			title = "O Recipiente de Muisek",
			hint = "Traga ao mandingueiro as ervas que ele espera de Orgrimmar.",
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} havia preparado as ervas, e ficou satisfeito com a cabeça que recebeu por elas. Uzer'i realizou seu ritual sobre o recipiente de imediato. Seu primeiro teste foi muito longe, entre os corujursos das {link:the-hinterlands}Terras Agrestes{/link}, e poria à prova tanto o ritual quanto o caçador que levava o recipiente.]=],
		},
		{
			title = "Armas de Espírito",
			hint = "Complete a coleção de espíritos do mandingueiro.",
			text = [=[Hipogrifo, dragão feérico, silvano e gigante da montanha: um a um, os aliados dos elfos noturnos foram encolhidos e capturados. Com madeira lascada, minerais, tendões e fragmentos de metal, Uzer'i prendeu seus espíritos para sempre nas armas que forjou.]=],
		},
	},
	mentions = {
		{ text = "Um Pedido Estranho" },
		{ text = "De Volta ao Mandingueiro Uzer'i" },
		{ text = "Testando o Recipiente" },
		{ text = "Muisek de Hipogrifo" },
		{ text = "Muisek de {link:the-drag}Drag{/link}ão Feérico" },
		{ text = "Muisek de Silvano" },
		{ text = "Muisek de Gigante da Montanha" },
		{ text = "Materiais Naturais" },
		{ text = "Armas de Espírito" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "troca ervas com ele" },
	},
})

