Translate("ptBR", "azj-tordin", {
	title = "Azj'Tordin",
	subtitle = "Ancião de Eldre'Thalas",
	found = "O Pavilhão Lariss",
	hint = [=[Procure o ancião que vive entre as ruínas do Pavilhão Lariss.]=],
	allegiance = "Nenhuma",
	sections = {
		{
			title = "Resumo",
			text = [=[Azj'Tordin é um ancião de Eldre'Thalas que escapou das garras de seu príncipe decaído. Pagou por sua liberdade com a imortalidade, e não se arrepende. Agora vive no {link:lariss-pavilion}Pavilhão Lariss{/link}, entre pedras antigas na floresta do leste.]=],
		},
		{
			title = "Importância",
			text = [=[Azj'Tordin deixou {red:dire-maul}Gládio Cruel{/red} por escolha própria, e pagou por isso. Na pressa da fuga, um diabrete demoníaco chamado Pusillin lhe roubou o livro de encantamentos e uma chave dos antigos salões da cidade. Ele já não se importa com a chave. Quer seu livro de volta.]=],
		},
		{
			title = "Feitos",
			text = [=[• Fugiu do príncipe decaído de Eldre'Thalas.
