Translate("ptBR", "falfindel-waywarder", {
	title = "Falfindel Waywarder",
	subtitle = "Druida de Thalanaar",
	found = "Thalanaar, na borda leste de Feralas",
	hint = [=[Procure o druida que cuida do posto de parada na borda leste da floresta.]=],
	allegiance = "Círculo Cenariano · Thalanaar",
	aliases = { "Falfindel" },
	sections = {
		{
			title = "Resumo",
			text = [=[Falfindel Waywarder é um druida dos elfos noturnos que cuida de {link:thalanaar}Thalanaar{/link}, o posto solitário onde as florestas de {link:feralas}Feralas{/link} encontram os cânions de {link:thousand-needles}Mil Agulhas{/link}. Os guardiões das {link:stonetalon-mountains}Torres de Pedra{/link} o chamam de grande e sábio. Diz-se que ele pode chamar os grandes espíritos da floresta para socorrer terras feridas.]=],
		},
		{
			title = "Importância",
			text = [=[De seu posto tranquilo, Falfindel vela por mais que {link:feralas}Feralas{/link}. Sua preocupação chega aos {link:the-barrens}Sertões{/link}, onde o lugar de descanso do semideus javali Agamaggan foi corrompido, e vai ao norte até a {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}, cujo guardião implorou sua ajuda.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estuda o que corrompeu o lugar de descanso de Agamaggan, no sul dos {link:the-barrens}Sertões{/link}.
• Enviou outros contra a bruxa velha {link:charlga-razorflank}Charlga Razorflank{/link}, do {link:razorfen-kraul}Urzal dos Tuscos{/link}.
• Atende à súplica do {link:keeper-albagorm}Guardião Albagorm{/link} para enviar espíritos da floresta ao {link:the-charred-vale}Vale Carbonizado{/link}.
• Espera os suprimentos que os mensageiros levam de {link:feathermoon-stronghold}Plumaluna{/link} através de {link:feralas}Feralas{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Bruxa do Urzal",
			hint = "Leve a Thalanaar o diário de um anão morto.",
			text = [=[O diário de Henrig Lonebrow falou a Falfindel do druida {link:heralath-fallowbrook}Heralath{/link}, capturado no Urzal, e de uma bruxa velha que ficava mais forte a cada dia. Não havia tempo para pedir ajuda a {link:darnassus}Darnassus{/link}. Quando o medalhão da bruxa voltou a ele, ele ousou esperar que seus estudos pudessem continuar, embora temesse que a resposta a eles fosse traição.]=],
		},
		{
			title = "Um Chamado das Torres de Pedra",
			hint = "Leve a súplica do Guardião Albagorm ao druida de Thalanaar.",
			text = [=[As harpias do {link:the-charred-vale}Vale Carbonizado{/link} haviam sido derrotadas, mas voltariam, e sementes sozinhas não poderiam curar o vale antes disso. {link:keeper-albagorm}Albagorm{/link} mandou uma mensagem através de meia {link:kalimdor}Kalimdor{/link} até Falfindel. O druida não desperdiçou palavras. Voltou-se de imediato a chamar ajuda da grande floresta.]=],
		},
		{
			title = "A Encomenda Atrasada",
			hint = "Traga a Thalanaar a encomenda perdida do mensageiro.",
			text = [=[A encomenda de {link:feathermoon-stronghold}Plumaluna{/link} chegou atrasada e pela mão de um estranho. Falfindel adivinhou de imediato que algo acontecera a {link:raschal-the-courier}Raschal{/link}, o mensageiro de costume. Tinha suas próprias suspeitas: os Patábua andavam inquietos ultimamente, agitados por algo ao sul.]=],
		},
	},
	mentions = {
		{ text = "Diário do Monocelha" },
		{ text = "A Bruxa do Urzal" },
		{
			text = [=[Recuperando o {link:the-charred-vale}Vale Carbonizado{/link}, a súplica das {link:stonetalon-mountains}Torres de Pedra{/link}]=],
		},
		{ text = "Entrega em {link:thalanaar}Thalanaar{/link}" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Guardião Albagorm", note = "pediu sua ajuda" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "o druida capturado no Urzal" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "inimiga" },
		{ id = "raschal-the-courier", name = "Raschal, o Mensageiro", note = "seu mensageiro de costume" },
	},
})

